int findKthLargest(vector<int> nums, int k) {
    int target = (int)nums.size() - k;      // index in ascending order
    int lo = 0, hi = (int)nums.size() - 1;
    mt19937 rng(random_device{}());
    while (true) {
        int pivot = nums[lo + rng() % (hi - lo + 1)];
        // 3-way partition: [lo,lt) < pivot, [lt,gt] == pivot, (gt,hi] > pivot
        int lt = lo, i = lo, gt = hi;
        while (i <= gt) {
            if (nums[i] < pivot) swap(nums[lt++], nums[i++]);
            else if (nums[i] > pivot) swap(nums[i], nums[gt--]);
            else ++i;
        }
        if (target < lt) hi = lt - 1;
        else if (target > gt) lo = gt + 1;
        else return pivot;                   // target falls in the == block
    }
}

import heapq

def last_stone_weight(stones: list[int]) -> int:
    h = [-s for s in stones]        # heapq is a min-heap: negate for max
    heapq.heapify(h)                 # O(n)
    while len(h) > 1:
        x = -heapq.heappop(h)
        y = -heapq.heappop(h)
        if x != y:
            heapq.heappush(h, -(x - y))
    return -h[0] if h else 0

vector<string> topKFrequent(const vector<string>& words, int k) {
    unordered_map<string, int> freq;
    for (const auto& w : words) ++freq[w];
    // "a is better than b": higher count, then smaller word.
    // priority_queue keeps the worst kept word on top.
    auto better = [](const pair<int, string>& a, const pair<int, string>& b) {
        return a.first > b.first || (a.first == b.first && a.second < b.second);
    };
    priority_queue<pair<int, string>, vector<pair<int, string>>, decltype(better)> pq(better);
    for (const auto& [w, c] : freq) {
        pq.push({c, w});
        if ((int)pq.size() > k) pq.pop();        // evict the worst
    }
    vector<string> out;
    while (!pq.empty()) { out.push_back(pq.top().second); pq.pop(); }
    reverse(out.begin(), out.end());              // worst came out first
    return out;
}

