class MedianFinder {
    priority_queue<int> lo;                              // max-heap: lower half
    priority_queue<int, vector<int>, greater<int>> hi;   // min-heap: upper half
public:
    // invariant: every lo <= every hi, and lo.size() == hi.size() or hi.size() + 1
    void addNum(int x) {
        if (lo.empty() || x <= lo.top()) lo.push(x);
        else hi.push(x);
        if (lo.size() > hi.size() + 1) { hi.push(lo.top()); lo.pop(); }
        else if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop(); }
    }
    double findMedian() const {
        if (lo.size() > hi.size()) return lo.top();
        // average in double: lo.top() + hi.top() can overflow int
        return ((double)lo.top() + (double)hi.top()) / 2.0;
    }
};

int minStoneSum(vector<int>& piles, int k) {
    priority_queue<int> pq(piles.begin(), piles.end());   // O(n) build
    while (k-- > 0) {
        int p = pq.top();
        if (p <= 1) break;            // nothing left to remove anywhere
        pq.pop();
        pq.push(p - p / 2);
    }
    long long total = 0;              // n * 1e4 fits in int, but be safe
    while (!pq.empty()) { total += pq.top(); pq.pop(); }
    return (int)total;
}

int maxEvents(vector<vector<int>>& events) {
    sort(events.begin(), events.end());                  // by start
    priority_queue<int, vector<int>, greater<int>> ends; // ends of open events
    int n = events.size(), i = 0, attended = 0;
    int day = 0;
    while (i < n || !ends.empty()) {
        if (ends.empty()) day = max(day, events[i][0]);  // skip empty days
        while (i < n && events[i][0] <= day) ends.push(events[i++][1]);
        while (!ends.empty() && ends.top() < day) ends.pop();  // expired
        if (!ends.empty()) { ends.pop(); ++attended; }   // earliest deadline
        ++day;
    }
    return attended;
}

