struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v, ListNode* n = nullptr) : val(v), next(n) {}
};

ListNode* mergeKLists(vector<ListNode*>& lists) {
    // min-heap by value: comparator says "a after b" when a->val > b->val
    auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; };
    priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);
    for (ListNode* h : lists) if (h) pq.push(h);     // skip empty lists
    ListNode dummy(0);
    ListNode* tail = &dummy;
    while (!pq.empty()) {
        ListNode* node = pq.top(); pq.pop();
        tail->next = node;
        tail = node;
        if (node->next) pq.push(node->next);          // advance that list
    }
    tail->next = nullptr;
    return dummy.next;
}

import heapq

def k_closest(points: list[tuple[int, int]], k: int) -> list[tuple[int, int]]:
    heap = []                        # max-heap by distance via negation
    for x, y in points:
        d = x * x + y * y            # squared distance: no sqrt needed
        if len(heap) < k:
            heapq.heappush(heap, (-d, x, y))
        elif d < -heap[0][0]:        # closer than the farthest kept point
            heapq.heapreplace(heap, (-d, x, y))
    return [(x, y) for _, x, y in heap]

vector<vector<int>> getSkyline(const vector<vector<int>>& buildings) {
    // start -> (x, -h), end -> (x, +h). Lexicographic sort puts at the same x:
    // starts before ends, taller starts first, lower ends first.
    vector<pair<int, int>> ev;
    for (const auto& b : buildings) {
        ev.push_back({b[0], -b[2]});
        ev.push_back({b[1], b[2]});
    }
    sort(ev.begin(), ev.end());
    multiset<int> active = {0};          // ground level is always present
    vector<vector<int>> out;
    int prev = 0;
    for (auto [x, h] : ev) {
        if (h < 0) active.insert(-h);
        else active.erase(active.find(h));   // erase ONE copy only
        int cur = *active.rbegin();
        if (cur != prev) {
            if (!out.empty() && out.back()[0] == x) out.back()[1] = cur;  // same x
            else out.push_back({x, cur});
            prev = cur;
        }
    }
    return out;
}

// שורות ועמודות ממוינות בסדר עולה; 1 <= k <= n*n
int kthSmallest(const vector<vector<int>>& m, int k) {
    int n = m.size();
    long long lo = m[0][0], hi = m[n - 1][n - 1];
    while (lo < hi) {                                  // הערך הקטן ביותר שיש לפחות k איברים <= לו
        long long mid = lo + (hi - lo) / 2;
        int cnt = 0, col = n - 1;
        for (int r = 0; r < n; ++r) {                  // staircase: O(n) לספירה
            while (col >= 0 && m[r][col] > mid) --col;
            cnt += col + 1;
        }
        if (cnt >= k) hi = mid; else lo = mid + 1;
    }
    return (int)lo;                                    // lo תמיד ערך שקיים במטריצה
}

// heap: max-heap תקין במערך; לא משנים אותו
vector<int> topK(const vector<int>& heap, int k) {
    vector<int> out;
    if (heap.empty()) return out;
    priority_queue<pair<int, int>> pq;              // (value, index)
    pq.push({heap[0], 0});
    while (!pq.empty() && (int)out.size() < k) {
        auto [v, i] = pq.top(); pq.pop();
        out.push_back(v);
        for (int c : {2 * i + 1, 2 * i + 2})
            if (c < (int)heap.size()) pq.push({heap[c], c});
    }
    return out;
}

import heapq

class SortedIterator:
    def __init__(self, lists):
        self.lists = lists
        # one entry per non-empty list: (value, list index, position)
        self.heap = [(lst[0], i, 0) for i, lst in enumerate(lists) if lst]
        heapq.heapify(self.heap)                      # O(k)

    def has_next(self):
        return bool(self.heap)

    def next(self):
        if not self.heap:
            raise StopIteration
        val, i, j = heapq.heappop(self.heap)          # O(log k)
        if j + 1 < len(self.lists[i]):
            heapq.heappush(self.heap, (self.lists[i][j + 1], i, j + 1))
        return val

